import{Ht as e,Rt as t,dt as n,gt as r,mt as i,n as a}from"./chunks/framework.BkIgthgQ.js";var o=JSON.parse(`{"title":"Multi-node","description":"Multiple processes need S3 and Redis. cluster.download: public S3 vs local proxy.","frontmatter":{"title":"Multi-node","description":"Multiple processes need S3 and Redis. cluster.download: public S3 vs local proxy."},"headers":[],"relativePath":"en/guide/features/cluster.md","filePath":"en/guide/features/cluster.md","lastUpdated":1790057721000}`),s={name:`en/guide/features/cluster.md`};function c(a,o,s,c,l,u){let d=e(`Mermaid`);return t(),n(`div`,null,[o[0]||=i(`<h1 id="multi-node" tabindex="-1">Multi-node <a class="header-anchor" href="#multi-node" aria-label="Permalink to “Multi-node”">​</a></h1><p>Cluster mode is multiple KiriVers processes sharing one Postgres and object store.</p><h2 id="when-to-use" tabindex="-1">When to use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to “When to use”">​</a></h2><p>Scale downloads or admin horizontally. A single-disk install can stay one process.</p><h2 id="configuration-entry" tabindex="-1">Configuration entry <a class="header-anchor" href="#configuration-entry" aria-label="Permalink to “Configuration entry”">​</a></h2><p>Requires <code>storage.driver=s3</code> <strong>and</strong> <code>cache.driver=redis</code>. Otherwise <code>cluster.download</code> is ignored. YAML: <a href="/en/guide/config/cluster">Cluster</a>, <a href="/en/guide/config/cache">Redis</a>, <a href="/en/guide/config/s3">S3</a>. Console: <a href="/en/admin/nodes">Nodes</a>.</p><h2 id="rules" tabindex="-1">Rules <a class="header-anchor" href="#rules" aria-label="Permalink to “Rules”">​</a></h2><table tabindex="0"><thead><tr><th><code>cluster.download</code></th><th>Behavior</th></tr></thead><tbody><tr><td><code>s3</code></td><td>Public object URLs, CDN-friendly</td></tr><tr><td><code>local</code></td><td>Node proxy; check is also <code>private, no-store</code></td></tr></tbody></table><p><code>node.display_name</code> is a label only. Heartbeat writes Postgres; nodes do not report over HTTP.</p><h2 id="client-duties" tabindex="-1">Client duties <a class="header-anchor" href="#client-duties" aria-label="Permalink to “Client duties”">​</a></h2><p>Do not CDN-cache check under local-proxy. Download URLs remain SHA-256 objects.</p>`,11),r(d,{code:`flowchart%20LR%0A%20%20C%5BClient%5D%20--%3E%20P1%5BKiriVers%20node%20A%5D%0A%20%20C%20--%3E%20P2%5BKiriVers%20node%20B%5D%0A%20%20P1%20--%3E%20PG%5B(PostgreSQL)%5D%0A%20%20P2%20--%3E%20PG%0A%20%20P1%20--%3E%20R%5B(Redis)%5D%0A%20%20P2%20--%3E%20R%0A%20%20P1%20--%3E%20S3%5B(Object%20storage)%5D%0A%20%20P2%20--%3E%20S3%0A`})])}var l=a(s,[[`render`,c]]);export{o as __pageData,l as default};